{
  "command": "node <<'NODE'
const fs = require('fs');
const path = require('path');
const root = '.ypi/tasks/20260728-160223-修复代码匹配一键匹配模式数据过多时无法滚动问题';
const required = ['brief.md','prd.md','ui.md','design.md','implement.md','checks.md','plan-review.md','code-match-scroll-prototype.html'];
for (const file of required) {
  const p = path.join(root, file);
  if (!fs.existsSync(p)) throw new Error(`missing ${file}`);
  const text = fs.readFileSync(p, 'utf8');
  if (text.includes('_TBD by YPI Studio workflow._')) throw new Error(`TBD remains in ${file}`);
  if (text.trim().length < 200) throw new Error(`too short ${file}`);
}
const implement = fs.readFileSync(path.join(root, 'implement.md'), 'utf8');
const match = implement.match(/```json ypi-implementation-plan\n([\s\S]*?)\n```/);
if (!match) throw new Error('implementation plan block missing');
const plan = JSON.parse(match[1]);
if (plan.schemaVersion !== 2 || plan.maxConcurrency !== 1 || plan.subtasks.length !== 2) throw new Error('unexpected implementation plan shape');
for (const item of plan.subtasks) {
  for (const key of ['id','title','phase','order','dependsOn','files','instructions','acceptance','validation','risks','parallelizable','localReview']) {
    if (!(key in item)) throw new Error(`${item.id} missing ${key}`);
  }
}
for (const md of ['ui.md','plan-review.md']) {
  const text = fs.readFileSync(path.join(root, md), 'utf8');
  for (const m of text.matchAll(/\]\(\.\/([^)#?]+)(?:[)#?][^)]*)?\)/g)) {
    const target = decodeURIComponent(m[1]);
    if (!fs.existsSync(path.join(root, target))) throw new Error(`${md} broken link ${target}`);
  }
}
const html = fs.readFileSync(path.join(root, 'code-match-scroll-prototype.html'), 'utf8');
for (const token of ['data-state="6"','data-state="50"','data-state="120"','data-state="empty"','data-state="error"','data-state="loading"','data-view="desktop"','data-view="low"','data-view="mobile"','code-match-results-list','editor-scroll']) {
  if (!html.includes(token)) throw new Error(`prototype missing ${token}`);
}
const script = html.match(/<script>([\s\S]*?)<\/script>/)?.[1];
if (!script) throw new Error('prototype script missing');
new Function(script);
console.log(`artifact validation passed: ${required.length} files, ${plan.subtasks.length} plan subtasks, prototype script syntax OK`);
NODE

printf '\n--- task artifact status ---\n'
git status --short -- '.ypi/tasks/20260728-160223-修复代码匹配一键匹配模式数据过多时无法滚动问题'

printf '\n--- production diff touched by this planning directory check ---\n'
find '.ypi/tasks/20260728-160223-修复代码匹配一键匹配模式数据过多时无法滚动问题' -maxdepth 1 -type f -print | sort",
  "timeout": 30
}
